export interface ExchangeRates { rateFor(from: Currency, to: Currency): number; }

export class ExchangeService {
  constructor(private readonly rates: ExchangeRates) {}   // injected, never reassigned

  convert(amount: Money, target: Currency): Money {
    return amount.times(this.rates.rateFor(amount.currency, target)).in(target);
  }
}

